using System.Text.Json.Serialization;
using CampaignVault.Data.Templates;

namespace CampaignVault.Models;

/// <summary>
/// Per-campaign configuration document.
/// 
/// Document ID is now generated by <see cref="Data.CampaignDocumentKeys.Config"/> (e.g. "campaigns/{name}/config").
/// This replaces the old implicit singleton "campaign/config" pattern.
/// 
/// Controls the (locked) ruleset system for the campaign + any house-rule overrides.
/// Loaded by RulesetActionHandler on every ruleset action dispatch.
/// </summary>
public class CampaignConfig
{
    /// <summary>
    /// Document ID. Should be set via CampaignDocumentKeys.Config(campaignName) rather than hardcoded.
    /// Kept mutable for Raven load/store compatibility.
    /// </summary>
    public string Id { get; set; } = null!;

    /// <summary>
    /// The active TTRPG ruleset for this campaign.
    /// Determines which IRulesetResolver handles RulesetAction WorldChanges.
    ///
    /// This value is locked at the Campaign level once the campaign is initialized
    /// (see first-class Campaign model + InitializeCampaign tool).
    ///
    /// String ID enables plugin-contributed systems backed by YAML data.
    /// </summary>
    public string ActiveSystem { get; set; } = RulesetSystem.Dnd5e;

/// <summary>
    /// Optional house-rule overrides passed to resolvers.
    /// Keys and values are resolver-specific. Examples:
    /// "lingeringInjuries" → "true" (D&D 5e optional rule)
    /// "mapEnabled" → "true" (PF2e multi-attack penalty tracking)
    /// </summary>
    public Dictionary<string, string> SystemOptions { get; set; } = [];

    /// <summary>
    /// Maximum number of pressure nags to surface in a single tool response.
    /// Defaults to 5.
    /// </summary>
    public int MaxPressuresPerResponse { get; set; } = 5;

    /// <summary>
    /// Maximum number of guidance hints to surface in a single tool response.
    /// Defaults to 2.
    /// </summary>
    public int MaxGuidanceHintsPerResponse { get; set; } = 2;

    /// <summary>
    /// Maximum characters (text + example) for guidance hints in a single tool response.
    /// Defaults to 600 chars (~150 tokens).
    /// </summary>
    public int MaxGuidanceCharsPerResponse { get; set; } = 600;

    /// <summary>
    /// When true, guidance hints are collected and delivered on tool responses.
    /// Defaults to true.
    /// </summary>
    public bool GuidanceEnabled { get; set; } = true;

    /// <summary>
    /// The number of in-game days a pressure nag is suppressed after being surfaced.
    /// Defaults to 1 (meaning it stays hidden for 1 day, then reappears if ignored).
    /// </summary>
    public int PressureCooldownDays { get; set; } = 1;

    /// <summary>
    /// The number of times a pressure nag is suppressed before escalating to ENGINE WARNING.
    /// Defaults to 3.
    /// </summary>
    public int PressureEscalationCount { get; set; } = 3;

    /// <summary>
    /// The number of in-game days before a Trivial memory drifts or decays.
    /// Defaults to 20.
    /// </summary>
    public int MemoryTrivialDecayDays { get; set; } = 20;

    /// <summary>
    /// The number of in-game days before an Important memory drifts or decays.
    /// Defaults to 40.
    /// </summary>
    public int MemoryImportantDecayDays { get; set; } = 40;

    /// <summary>
    /// The number of in-game days before economic demand drifts or decays.
    /// Defaults to 7.
    /// </summary>
    public int EconomicDemandDecayDays { get; set; } = 7;

    /// <summary>
    /// Base per-day need accumulation rate during simulation (multiplied by days passed).
    /// Defaults to 10.
    /// </summary>
    public float NeedAccumulationRate { get; set; } = 10f;

    /// <summary>
    /// Baseline need level that scheduled activities settle NPCs toward.
    /// Routines matching "eat" keywords settle hunger to this value; "sleep" settles tiredness, etc.
    /// Defaults to 20.
    /// </summary>
    public int? NeedSatisfactionBaseline { get; set; } = 20;

    /// <summary>
    /// Multiplier applied to thirst need accumulation.
    /// Defaults to 1.2.
    /// </summary>
    public float ThirstAccumulationMultiplier { get; set; } = 1.2f;

    /// <summary>
    /// Multiplier applied to tiredness need accumulation.
    /// Defaults to 0.8.
    /// </summary>
    public float TirednessAccumulationMultiplier { get; set; } = 0.8f;

    /// <summary>
    /// Per-day morale drift when NPCs are in sustained bad need states.
    /// Defaults to -0.8.
    /// </summary>
    public float MoraleDriftPerDay { get; set; } = -0.8f;

    /// <summary>
    /// Grace period (in days) before transient NPCs are evicted from unvisited locations.
    /// Defaults to 1.
    /// </summary>
    public int TransientEvictionGraceDays { get; set; } = 1;

    /// <summary>
    /// Number of commits with no recorded time passage (no day-boundary crossing, no MinutesElapsed
    /// on any change) before TimeStalenessPressureContributor nudges the DM-LLM to record narrative
    /// time passage. Defaults to 15.
    /// </summary>
    public int TimeStalenessNudgeThreshold { get; set; } = 15;

    /// <summary>
    /// Days a rumor must age without resolution before surfacing world pressure.
    /// Defaults to 5.
    /// </summary>
    public int RumorAgingPressureDays { get; set; } = 5;

    /// <summary>
    /// Days a forgotten rumor must age before being archived (deleted) from the campaign.
    /// Defaults to 30.
    /// </summary>
    public int RumorArchiveAfterDays { get; set; } = 30;

    /// <summary>
    /// Days without quest progress before staleness pressure is surfaced.
    /// Defaults to 10.
    /// </summary>
    public int QuestStalenessDays { get; set; } = 10;

    /// <summary>
    /// Days a plot thread can sit at Climax before auto-resolving with a disaster outcome.
    /// Defaults to 10.
    /// </summary>
    public int PlotThreadClimaxAutoResolveDays { get; set; } = 10;

    /// <summary>
    /// HP ratio threshold (current/max) below which a character is considered critically wounded.
    /// Defaults to 0.25.
    /// </summary>
    public float CharacterPressureHpCriticalThreshold { get; set; } = 0.25f;

    public float TensionWeightNeed { get; set; } = 0.30f;
    public float TensionWeightMemory { get; set; } = 0.25f;
    public float TensionWeightRelational { get; set; } = 0.25f;
    public float TensionWeightDisposition { get; set; } = 0.20f;

    /// <summary>
    /// Weight for scene-local "idle beats without acting" stress (<see cref="Character.IdleSceneBeats"/>) —
    /// independent of need/memory/relational/disposition state, so a companion who's been quietly present
    /// through several beats of banter still accrues tension even with no backstory driving it. Renormalized
    /// alongside the other four weights (see DefaultBehavioralTensionCalculator.NormalizeWeights), so this
    /// doesn't need to be netted out of the others by hand.
    /// </summary>
    public float TensionWeightMomentum { get; set; } = 0.15f;

    /// <summary>
    /// Consecutive on-screen beats without acting before a companion/keepAlive NPC surfaces a Normal-urgency
    /// "hasn't acted in a while" initiative candidate. See SceneMomentumInitiativeProvider.
    /// </summary>
    public int MomentumIdleBeatsNormalThreshold { get; set; } = 4;

    /// <summary>
    /// Consecutive idle beats before the momentum candidate escalates to High urgency — at which point it's
    /// also mirrored into WorldPressure as a NARRATIVE PROMPT (see UrgentInitiativePressureContributor).
    /// </summary>
    public int MomentumIdleBeatsHighThreshold { get; set; } = 8;

    /// <summary>
    /// How many of the most-recent per-turn initiative-slot winners (Campaign.RecentInitiativeSlotNpcIds)
    /// are tracked and penalized. See MutationTools.SelectAndEnrichInitiativeAsync.
    /// </summary>
    public int InitiativeCooldownSize { get; set; } = 5;

    /// <summary>
    /// Flat priority penalty applied when selecting this turn's single initiative-enrichment slot to any
    /// NPC still in Campaign.RecentInitiativeSlotNpcIds — the anti-starvation term that keeps one
    /// consistently-high-priority NPC (e.g. a bold, frequently-idle companion) from winning every turn.
    /// </summary>
    public float InitiativeCooldownPenalty { get; set; } = 30f;

    public float TensionValencePositive { get; set; } = 0.3f;
    public float TensionValenceNeutral { get; set; } = 0.5f;
    public float TensionValenceNegative { get; set; } = 0.8f;
    public float TensionValenceTraumatic { get; set; } = 1.0f;

    public float NeedConflictThreshold { get; set; } = 70f;
    public float NeedConflictTensionBoost { get; set; } = 15f;

    public int DispositionMinTokenLength { get; set; } = 3;
    public Dictionary<string, List<string>> DispositionKeywordExpansions { get; set; } = [];

    // Deliberately empty by default — see GratitudeHeuristicHelper.DefaultTokens for the fallback.
    // RavenDB's deserializer appends onto (rather than replaces) a pre-populated List<T> property,
    // so a non-empty default here doubles on every load and compounds permanently on load-then-save.
    public List<string> GratitudeHeuristicTokens { get; set; } = [];

    public int InitiativeSuppressionRetentionDays { get; set; } = 30;

    /// <summary>
    /// BehavioralTension (0-100 scale) threshold above which an NPC's top initiative candidate (if
    /// Urgency is at least High) produces an advisory TurnIntentSignal suggesting the NPC should
    /// act/speak next. Defaults to 40 — still gated by the High-urgency candidate requirement, so
    /// this alone doesn't make NPCs trigger-happy, just lets ordinary (non-crisis) tension prompt
    /// them to act instead of only firing near max stress. Never a hard gate — the player can
    /// always act regardless.
    /// </summary>
    public double BehavioralTensionSpeakingThreshold { get; set; } = 40;

    /// <summary>
    /// Days after a persistent relationship initiative was surfaced before sim may re-arm it
    /// (affection, resentment, trust bands only).
    /// </summary>
    public int RelationalRearmIntervalDays { get; set; } = 7;

    /// <summary>
    /// Days since a party companion's last recorded Conversation event (while a PC is present in the
    /// scene) before ConversationStalenessInitiativeProvider surfaces a "hasn't spoken up in a while"
    /// candidate. Only fires when a prior Conversation event exists at all — a companion with no
    /// conversation history yet (e.g. freshly introduced) doesn't fire on day one.
    /// </summary>
    public int ConversationStalenessDaysThreshold { get; set; } = 2;

    /// <summary>
    /// Per-campaign resource pool definitions (spell slots, focus points, action points, etc.).
    /// If empty, built-in defaults are loaded based on ActiveSystem.
    /// Allows homebrew variants and custom systems.
    /// Key = pool name (e.g., "spell_slots_1", "focus_points").
    /// </summary>
    public Dictionary<string, ResourcePoolTemplate> ResourcePoolSchemas { get; set; } = [];

    /// <summary>
    /// When true, relationship modifiers on social skill checks use the reverse relationship as a fallback
    /// if the target has no recorded opinion of the actor (reads half of actor → target relationship, rounded down).
    /// Defaults to false — only target → actor relationships directly modify rolls.
    /// </summary>
    public bool SymmetricRelationshipFallback { get; set; } = false;

    /// <summary>
    /// When true, the engine automatically repairs one-way location exits by appending reverse exits
    /// when they are missing (unless the forward exit is marked OneWay: true).
    /// Defaults to false — many campaigns use intentional one-way exits (chutes, secret doors, traps).
    /// </summary>
    public bool AutoRepairLocationConnectivity { get; set; } = false;

    /// <summary>
    /// Number of events surfaced in ambient "story so far" context (get_world_state, get_scene).
    /// Selected by importance (Core/Important survive first), then recency. Defaults to 5.
    /// </summary>
    public int EventContextBudgetAmbient { get; set; } = 5;

    /// <summary>
    /// Number of events surfaced in get_npc_context. Defaults to 10.
    /// </summary>
    public int EventContextBudgetNpc { get; set; } = 10;

    /// <summary>
    /// Default number of events returned by recall_history when the caller doesn't override via `limit`.
    /// Defaults to 5.
    /// </summary>
    public int EventContextBudgetRecall { get; set; } = 5;

    /// <summary>
    /// XP progression type for this campaign.
    /// Standard = PHB default, Slow = half XP, Fast = double XP, Milestone = narrative leveling only (no XP tracking).
    /// </summary>
    public XpProgressionType XpProgression { get; set; } = XpProgressionType.Standard;

    /// <summary>
    /// Custom XP thresholds per level (level -> XP required). If empty, uses built-in table for XpProgression type.
    /// Key = target level (e.g., "2" = XP needed to reach level 2), Value = cumulative XP required.
    /// </summary>
    public Dictionary<int, int> CustomXpThresholds { get; set; } = [];

    /// <summary>
    /// When true, surfaces a pressure when a character reaches XP threshold for next level.
    /// Defaults to true.
    /// </summary>
    public bool AutoLevelUpPrompt { get; set; } = true;

    /// <summary>
    /// Number of take_turn calls between forced full-detail reseeds when delta mode is active.
    /// Imprecision is fine — this is a token-budget heuristic, not a correctness guarantee. Signal-driven
    /// triggers (DetectAndApplyReseedTriggersAsync) already force an earlier reseed on major location/
    /// relationship/plot-tension beats; this interval is a backstop for slow drift and caller-forgotten
    /// forceFullReseed, not the primary reseed mechanism. Defaults to 40.
    /// </summary>
    public int DeltaModeReseedIntervalTurns { get; set; } = 40;

    /// <summary>
    /// Master switch for take_turn's Full/Delta response alternation. When false, every call behaves
    /// as a full reseed (pre-delta-mode behavior). Defaults to true.
    /// </summary>
    public bool DeltaModeEnabled { get; set; } = true;

    /// <summary>
    /// Minimum |delta| (absolute value, single-turn max across all NeedChange entries for that need)
    /// for a need to be considered a significant mover on mode=delta take_turn calls — needs below this
    /// are filtered out of KnownNeeds rather than re-sent unchanged. Not derived from a fixed need scale:
    /// core needs (hunger/thirst/tiredness/stress/fatigue) are documented 0-100, but needs are otherwise
    /// unrestricted (the LLM can invent any name on any implicit scale), so this is a tunable heuristic,
    /// not a calibrated constant. Defaults to 2.
    /// </summary>
    public float NeedsChangeSignificanceThreshold { get; set; } = 2f;
}

/// <summary>
/// XP progression speed for the campaign.
/// </summary>
[JsonConverter(typeof(JsonStringEnumConverter))]
public enum XpProgressionType
{
    /// <summary>Standard PHB progression (D&D 5e default).</summary>
    Standard,
    /// <summary>Half XP required per level (slower leveling).</summary>
    Slow,
    /// <summary>Double XP required per level (faster leveling).</summary>
    Fast,
    /// <summary>Milestone leveling only — no XP tracking, level_up changes are narrative-only.</summary>
    Milestone
}

/// <summary>
/// Template for initializing a resource pool on character creation.
/// Used by character_create handler to populate Character.SystemExtension.ResourcePools.
/// Can be defined inline in CampaignConfig.ResourcePoolSchemas or loaded from YAML via ResourcePoolProvider.
/// </summary>
public record ResourcePoolTemplate : RulesetTemplate
{
    /// <summary>When this pool recovers. Null means "not set" — inherited from a parent template via YAML.</summary>
    [JsonPropertyName("recovery")]
    public RecoveryType? Recovery { get; set; }

    /// <summary>Base maximum value (can be overridden per-character based on level/class). Null = inherit from parent.</summary>
    [JsonPropertyName("defaultMax")]
    public int? DefaultMax { get; set; }

    /// <summary>TTRPG systems this pool applies to ("dnd5e", "pf2e"). Null = all systems.</summary>
    [JsonPropertyName("applicableSystems")]
    public List<string>? ApplicableSystems { get; set; }

    /// <summary>
    /// Classes that receive this pool (substring match on class name, e.g. "monk", "battle master").
    /// Null = not class-gated (spell slot pools use caster-level rules instead).
    /// </summary>
    [JsonPropertyName("applicableClasses")]
    public List<string>? ApplicableClasses { get; set; }

    /// <summary>For slot-based pools: map character level to max count. E.g., "1" -> 4, "2" -> 3 for spell slots.</summary>
    [JsonPropertyName("levelToMaxMap")]
    public Dictionary<string, int>? LevelToMaxMap { get; set; }

    /// <summary>
    /// When true, pool is only initialized via <see cref="FeatDefinition.ExtraPools"/>, not class/caster rules.
    /// </summary>
    [JsonPropertyName("featGrantedOnly")]
    public bool? FeatGrantedOnly { get; set; }

    /// <summary>
    /// Merge two templates: child fields win; parent fills gaps.
    /// Used by RulesetTemplateResolver during YAML inheritance resolution.
    /// </summary>
    public static ResourcePoolTemplate Merge(ResourcePoolTemplate child, ResourcePoolTemplate parent)
    {
        var merged = child with
        {
            Description = child.Description ?? parent.Description,
            Recovery = child.Recovery ?? parent.Recovery,
            DefaultMax = child.DefaultMax ?? parent.DefaultMax,
            ApplicableSystems = child.ApplicableSystems?.Count > 0
                ? child.ApplicableSystems
                : parent.ApplicableSystems,
            ApplicableClasses = child.ApplicableClasses?.Count > 0
                ? child.ApplicableClasses
                : parent.ApplicableClasses,
            FeatGrantedOnly = child.FeatGrantedOnly ?? parent.FeatGrantedOnly,
        };

        if (parent.LevelToMaxMap?.Count > 0)
        {
            var mergedMap = child.LevelToMaxMap != null
                ? new Dictionary<string, int>(child.LevelToMaxMap)
                : new Dictionary<string, int>();
            foreach (var (k, v) in parent.LevelToMaxMap)
                mergedMap.TryAdd(k, v);
            merged = merged with { LevelToMaxMap = mergedMap };
        }

        return merged;
    }
}
